def multiplicative_order(base, modulus):
    """Calculates the multiplicative order of base modulo modulus."""
    if base == 0 or base == 1:
        return 1 if base == 1 and modulus > 1 else 0

    from math import gcd

    # Euler's totient function
    def euler_phi(n):
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi = euler_phi(modulus)

    # Find prime factorization of phi
    factors = set()
    n = phi
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.add(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.add(n)

    order = phi

    # Check divisors of phi
    for p in factors:
        while order % p == 0 and pow(base, order // p, modulus) == 1:
            order //= p
    return order

