    if (a % m) == 1:
        return 1
    # Use the fact that the order must divide phi(m)
    import math
    def get_phi(n):
        res = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                res -= res // p
            p += 1
        if n > 1:
            res -= res // n
        return res

    phi = get_phi(m)
    # The order must be a divisor of phi
    # We find all divisors
    divs = []
    for i in range(1, int(phi**0.5) + 1):
        if phi % i == 0:
            divs.append(i)
            if i*i != phi:
                divs.append(phi // i)
    divs.sort()
    for d in divs:
        if pow(a, d, m) == 1:
            return d
    return None

